    /**
     * Tests getting all PaymentProcessors.
     *
     * @return    Collection
     */
    public List<PaymentProcessor> testGetAll() throws Throwable {
    LOGGER.info( "PaymentProcessorTest:testGetAll() - Retrieving Collection of PaymentProcessors:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PaymentProcessor : " );
    List<PaymentProcessor> collection  = null;

    try {
        // call the static get method on the PaymentProcessorService
        collection = service.getAllPaymentProcessor();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PaymentProcessor currEntity  = null;
            Iterator<PaymentProcessor> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPaymentProcessorId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

